      SUBROUTINE HUNT2CC     SEARCHES FOR AN EXIT FRINGE FIELD FOR A BENDING MAGNETCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM8H.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA, II, J, K, NUMA, TYPEN      LOGICAL         CKK      EXTERNAL        IDATAC--------------------------------------------------------------CC     CHECK FOR FOLLOWING FRINGE FIELD SPECIFICATIONC      DMC = .TRUE.      FFOUT = .FALSE.      J = NUM      DO 10 K = 1, 5      J = J + NDIF      IF (J .LE. 0) GO TO 50      IF (J .GT. NEL) GO TO 50      II = ISTOR(J)      TYPEN = IDATA(II)      IF (TYPEN .EQ. 2) GO TO 30      IF (TYPEN .NE. 13 .AND. TYPEN .NE. 23 .AND. TYPEN .NE. 30)      1    GO TO 50   10 CONTINUECC     DETERMINE IF IT PERTAINS TO THIS MAGNETC   30 NUMA = NUM      NUM = J      NUM2 = NUM      CALL CHEK(CKK)      DMC = BEFORE .OR. .NOT. CKK      FFOUT = .NOT. BEFORE      NUM = NUMA   50 RETURN      END